 * CSS specificity calculator and cascade sorter.
 *
 * specificity(selector) returns the [a, b, c] triple per the CSS spec:
 *   a = IDs
 *   b = classes, attributes, pseudo-classes
 *   c = elements (types) and pseudo-elements
 *
 * :not() and :is() contribute the specificity of their most specific
 * argument; :where() contributes zero. Combinators contribute nothing.
 */

const LEGACY_PSEUDO_ELEMENTS = new Set([
  "before",
  "after",
  "first-line",
  "first-letter",
]);

/** Functional pseudo-classes whose arguments are selector lists. */
const SELECTOR_LIST_PSEUDOS = new Set([
  "not",
  "is",
  "where",
  "matches",
  "-webkit-any",
  "-moz-any",
  "any",
]);

function isIdentStart(ch) {
  return /[A-Za-z_\u0080-\uFFFF]/.test(ch) || ch === "\\";
}

function isIdentChar(ch) {
  return /[A-Za-z0-9_\-\u0080-\uFFFF]/.test(ch) || ch === "\\";
}

/** Read an identifier starting at s[i], returning { name, end }. */
function readIdentifier(s, i) {
  let start = i;
  while (i < s.length && isIdentChar(s[i])) i++;
  return { name: s.slice(start, i), end: i };
}

/** Read a balanced parenthesized group starting at s[i] === '('. */
function readParens(s, i) {
  const start = i;
  let depth = 0;
  let quote = null;
  for (; i < s.length; i++) {
    const ch = s[i];
    if (quote) {
      if (ch === "\\") i++;
      else if (ch === quote) quote = null;
      continue;
    }
    if (ch === '"' || ch === "'") {
      quote = ch;
    } else if (ch === "(") {
      depth++;
    } else if (ch === ")") {
      depth--;
      if (depth === 0) return { text: s.slice(start, i + 1), end: i + 1 };
    }
  }
  throw new SyntaxError(`Unbalanced parentheses in selector: ${s}`);
}

/** Split a string on top-level commas (respecting quotes and parens). */
function splitTopLevel(s, sep = ",") {
  const parts = [];
  let depth = 0;
  let quote = null;
  let start = 0;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (quote) {
      if (ch === "\\") i++;
      else if (ch === quote) quote = null;
      continue;
    }
    if (ch === '"' || ch === "'") {
      quote = ch;
    } else if (ch === "(") {
      depth++;
    } else if (ch === ")") {
      depth--;
    } else if (ch === sep && depth === 0) {
      parts.push(s.slice(start, i));
      start = i + 1;
    }
  }
  parts.push(s.slice(start));
  return parts;
}

function maxOf(list) {
  // Take the most specific argument (component-wise max).
  return list.reduce((acc, t) => [
    Math.max(acc[0], t[0]),
    Math.max(acc[1], t[1]),
    Math.max(acc[2], t[2]),
  ], [0, 0, 0]);
}

function add(t1, t2) {
  return [t1[0] + t2[0], t1[1] + t2[1], t1[2] + t2[2]];
}

/** Parse a selector list like "a, .b #c". */
export function parseSelectorList(selector) {
  const trimmed = String(selector).trim();
  if (trimmed === "") throw new SyntaxError("Empty selector");
  return maxOf(
    splitTopLevel(trimmed).map((s) => parseComplex(s.trim()))
  );
}

/** Parse a complex selector: compounds joined by combinators. */
function parseComplex(selector) {
  const compounds = [];
  let buf = "";
  let quote = null;
  let depth = 0;
  let pendingCombinator = false;

  const flush = () => {
    const token = buf.trim();
    buf = "";
    if (!token) {
      if (compounds.length && !pendingCombinator) {
        throw new SyntaxError(`Invalid combinator in selector: ${selector}`);
      }
      return; // leading/trailing whitespace around a combinator
    }
    compounds.push(parseCompound(token));
    pendingCombinator = false;
  };

  for (let i = 0; i < selector.length; i++) {
    const ch = selector[i];
    if (quote) {
      buf += ch;
      if (ch === "\\") {
        buf += selector[++i] ?? "";
      } else if (ch === quote) {
        quote = null;
      }
      continue;
    }
    if (ch === '"' || ch === "'") {
      quote = ch;
      buf += ch;
      continue;
    }
    if (ch === "(") depth++;
    if (ch === ")") depth--;
    if (depth === 0 && (ch === ">" || ch === "+" || ch === "~")) {
      flush();
      pendingCombinator = true;
      continue;
    }
    if (depth === 0 && /\s/.test(ch)) {
      flush();
      continue;
    }
    buf += ch;
  }
  flush();

  if (!compounds.length) throw new SyntaxError(`Invalid selector: ${selector}`);
  return compounds.reduce(add, [0, 0, 0]);
}

/** Parse a single compound selector like "#main.item:hover". */
function parseCompound(compound) {
  let spec = [0, 0, 0];
  let i = 0;
  while (i < compound.length) {
    const ch = compound[i];

    if (ch === "#" || ch === ".") {
      const { name, end } = readIdentifier(compound, i + 1);
      if (!name) throw new SyntaxError(`Invalid selector: ${compound}`);
      spec = add(spec, [ch === "#" ? 1 : 0, ch === "." ? 1 : 0, 0]);
      i = end;
      continue;
    }

    if (ch === "[") {
      // Attribute selector; values may be quoted and contain ']'.
      let j = i + 1;
      let quote = null;
      while (j < compound.length) {
        const c = compound[j];
        if (quote) {
          if (c === "\\") j++;
          else if (c === quote) quote = null;
        } else if (c === '"' || c === "'") {
          quote = c;
        } else if (c === "]") {
          break;
        }
        j++;
      }
      if (compound[j] !== "]") {
        throw new SyntaxError(`Unterminated attribute selector: ${compound}`);
      }
      spec = add(spec, [0, 1, 0]);
      i = j + 1;
      continue;
    }

    if (ch === ":") {
      if (compound[i + 1] === ":") {
        // Explicit pseudo-element (::before, ::marker, ::slotted(...), ...)
        const { name, end } = readIdentifier(compound, i + 2);
        if (!name) throw new SyntaxError(`Invalid pseudo-element: ${compound}`);
        i = end;
        if (compound[i] === "(") {
          const { end: after } = readParens(compound, i);
          i = after;
        }
        spec = add(spec, [0, 0, 1]);
        continue;
      }

      const { name, end } = readIdentifier(compound, i + 1);
      if (!name) throw new SyntaxError(`Invalid pseudo-class: ${compound}`);
      let cursor = end;

      if (SELECTOR_LIST_PSEUDOS.has(name.toLowerCase())) {
        if (compound[cursor] !== "(") {
          throw new SyntaxError(`:${name}() requires arguments`);
        }
        const { text, end: after } = readParens(compound, cursor);
        const inner = text.slice(1, -1).trim();
        const args =
          inner === ""
            ? []
            : splitTopLevel(inner).map((arg) => parseSelectorList(arg.trim()));
        spec = add(spec, name.toLowerCase() === "where" ? [0, 0, 0] : maxOf(args));
        cursor = after;
      } else if (LEGACY_PSEUDO_ELEMENTS.has(name.toLowerCase())) {
        // Legacy single-colon syntax: :before, :after, :first-line, :first-letter
        spec = add(spec, [0, 0, 1]);
      } else {
        // Regular pseudo-class (:hover, :nth-child(2n+1), :lang(en), ...).
        spec = add(spec, [0, 1, 0]);
        if (compound[cursor] === "(") {
          const { end: after } = readParens(compound, cursor);
          cursor = after;
        }
      }
      i = cursor;
      continue;
    }

    if (ch === "*") {
      // Universal selector contributes nothing.
      i++;
      continue;
    }

    if (isIdentStart(ch)) {
      // Type selector.
      const { name, end } = readIdentifier(compound, i);
      if (/^[Nn][Ss]\|/.test(compound.slice(i))) {
        // Namespace prefix like svg|rect handled by identifier reader above;
        // treat "svg" as part of the type selector, not an element.
        spec = add(spec, [0, 0, 0]);
      } else {
        spec = add(spec, [0, 0, 1]);
      }
      void name;
      i = end;
      continue;
    }

    throw new SyntaxError(`Unexpected character '${ch}' in selector: ${compound}`);
  }

  return spec;
}

/**
 * Compute the specificity of a selector as [a, b, c]:
 *   a = number of ID selectors
 *   b = number of class selectors, attribute selectors, and pseudo-classes
 *   c = number of type selectors and pseudo-elements
 */
export function specificity(selector) {
  return parseSelectorList(selector);
}

/**
 * Sort rules by the CSS cascade order for equal origin/importance:
 * higher specificity wins; on ties, the later source order wins.
 *
 * @param {{ selector: string, sourceOrder: number }[]} rules
 * @returns sorted array (ascending: least to most winning)
 */
export function cascadeSort(rules) {
  return [...rules].sort((r1, r2) => {
    const s1 = specificity(r1.selector);
    const s2 = specificity(r2.selector);
    for (let i = 0; i < 3; i++) {
      if (s1[i] !== s2[i]) return s1[i] - s2[i];
    }
    return r1.sourceOrder - r2.sourceOrder;
  });
}
