result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/specificity/test/index.test.js", "content": "import { describe, it, expect } from "vitest";
import { specificity, cascadeSort } from "../src/index.js";

describe("specificity()", () => {
  // [selector, expected [a, b, c]]
  const table = [
    ["*", [0, 0, 0]],
    [":where(#a)", [0, 0, 0]],
    [":where(#a, .b.c)", [0, 0, 0]],
    ["li", [0, 0, 1]],
    ["ul li", [0, 0, 2]],
    ["nav ul li.active a", [0, 1, 4]], // 3 elements + .active class
    ["li::marker", [0, 0, 2]], // element + pseudo-element
    ["a::before", [0, 0, 2]],
    ["#main", [1, 0, 0]],
    ["#main .item:hover", [1, 2, 0]],
    [":is(#a, .b)", [1, 0, 0]], // most specific argument wins
    [":is(.a, .b.c) span", [0, 2, 1]],
    [":not(.active)", [0, 1, 0]],
    [":not(#top, section) > p", [1, 0, 2]],
    ['a[href^="https"]', [0, 1, 1]], // attribute selector with value
    ['input[type="text"].field', [0, 2, 1]],
    [".card.card--featured", [0, 2, 0]],
    ["h1 + p ~ div", [0, 0, 3]], // combinators contribute nothing
    ["div > #nav > ul > li:first-child", [1, 1, 4]],
    [":hover:focus", [0, 2, 0]],
    ["::selection", [0, 0, 1]],
    [":before", [0, 0, 1]], // legacy single-colon pseudo-element
    ["#s #s2 #s3 .x .y .z div div div", [3, 3, 3]],
    ["button[disabled]", [0, 1, 1]],
  ];

  it.each(table)("specificity(%j) => %j", (selector, expected) => {
    expect(specificity(selector)).toEqual(expected);
  });

  it("handles quoted values containing brackets and commas", () => {
    expect(specificity('a[data-x="],," ]')).toEqual([0, 1, 1]);
  });

  it("throws on invalid selectors", () => {
    expect(() => specificity("#")).toThrow();
    expect(() => specificity("")).toThrow();
  });
});

describe("cascadeSort()", () => {
  it("orders by specificity, then by source order on ties", () => {
    const rules = [
      { selector: "li", sourceOrder: 1 }, // [0,0,1]
      { selector: "ul li", sourceOrder: 2 }, // [0,0,2]
      { selector: "#main", sourceOrder: 3 }, // [1,0,0]
      { selector: ".item", sourceOrder: 4 }, // [0,1,0]
      { selector: "#main .item:hover", sourceOrder: 5 }, // [1,2,0]
      { selector: ".item.alt", sourceOrder: 6 }, // [0,2,0]
      { selector: "p", sourceOrder: 7 }, // [0,0,1] tie -> later than order 1
      { selector: ":is(#a, .b)", sourceOrder: 8 }, // [1,0,0] tie with #main
      { selector: ":where(#a)", sourceOrder: 9 }, // [0,0,0] least specific
    ];

    const sorted = cascadeSort(rules);
    expect(sorted.map((r) => r.sourceOrder)).toEqual([
      9, // :where(#a)          [0,0,0]
      1, // li                 [0,0,1]
      7, // p                  [0,0,1] (later)
      2, // ul li              [0,0,2]
      4, // .item              [0,1,0]
      6, // .item.alt          [0,2,0]
      3, // #main              [1,0,0]
      8, // :is(#a, .b)        [1,0,0] (later)
      5, // #main .item:hover  [1,2,0]
    ]);

    // Last entry is the winning rule.
    expect(sorted.at(-1).selector).toBe("#main .item:hover");
  });

  it("does not mutate the input array", () => {
    const rules = [
      { selector: "a", sourceOrder: 0 },
      { selector: "#id", sourceOrder: 1 },
    ];
    const copy = [...rules];
    cascadeSort(rules);
    expect(rules).toEqual(copy);
  });
});
